// App.js
import React, { useEffect, useRef, useState } from 'react';
import { Moon, Sun } from 'lucide-react';
import Lottie from 'lottie-react';
import codingAnimation from './coding.json';

const fullLines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"',
];

const sections = ['About', 'Skills', 'Projects', 'Experience', 'Contact'];

export default function App() {
  const [typedLines, setTypedLines] = useState([]);
  const [currentLine, setCurrentLine] = useState('');
  const [lineIndex, setLineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [loop, setLoop] = useState(0);
  const [activeSection, setActiveSection] = useState('About');
  const [darkMode, setDarkMode] = useState(true);
  const refs = useRef({});

  const highlightPartial = (line) => {
    const [left, rightRaw] = line.split('=');
    const variable = left?.trim();
    const right = rightRaw?.trim();

    return (
      <>
        <span className="text-[#9CDCFE]">{variable}</span>
        <span className="text-[#d4d4d4]"> = </span>
        {right ? (
          right.startsWith('"') ? (
            <span className="text-[#ce9178]">{right}</span>
          ) : (
            <span className="text-[#b5cea8]">{right}</span>
          )
        ) : null}
      </>
    );
  };

  const highlightLine = (line) => {
    const [left, right] = line.split('=');
    const variable = left?.trim();
    const value = right?.trim();

    return (
      <>
        <span className="text-[#9CDCFE]">{variable}</span>
        <span className="text-[#d4d4d4]"> = </span>
        {value?.startsWith('"') ? (
          <span className="text-[#ce9178]">{value}</span>
        ) : (
          <span className="text-[#b5cea8]">{value}</span>
        )}
      </>
    );
  };

  useEffect(() => {
    if (lineIndex < fullLines.length) {
      if (charIndex < fullLines[lineIndex].length) {
        const timeout = setTimeout(() => {
          setCurrentLine(prev => prev + fullLines[lineIndex][charIndex]);
          setCharIndex(i => i + 1);
        }, 40);
        return () => clearTimeout(timeout);
      } else {
        const timeout = setTimeout(() => {
          setTypedLines(prev => [...prev, fullLines[lineIndex]]);
          setCurrentLine('');
          setCharIndex(0);
          setLineIndex(i => i + 1);
        }, 300);
        return () => clearTimeout(timeout);
      }
    } else {
      const timeout = setTimeout(() => {
        setTypedLines([]);
        setCurrentLine('');
        setCharIndex(0);
        setLineIndex(0);
        setLoop(l => l + 1);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  }, [charIndex, lineIndex, loop]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { threshold: 0.5 }
    );

    sections.forEach(sec => {
      const el = refs.current[sec.toLowerCase()];
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  const bgClass = darkMode ? 'bg-[#1e1e1e] text-[#d4d4d4]' : 'bg-white text-black';
  const sidebarClass = darkMode ? 'bg-[#252526]' : 'bg-gray-200';

  return (
    <div className={`relative flex ${bgClass} font-mono text-base`}>
      {/* Theme toggle button in top-right corner */}
      <button
        onClick={() => setDarkMode(!darkMode)}
        className="fixed top-4 right-4 z-50 p-2 rounded-full border hover:bg-gray-400 hover:text-white"
      >
        {darkMode ? <Sun size={18} /> : <Moon size={18} />}
      </button>

      {/* Sidebar */}
      <div className={`fixed top-0 left-0 h-screen w-24 ${sidebarClass} flex flex-col items-center space-y-4 py-6 z-40`}>
        {sections.map(sec => (
          <a
            key={sec}
            href={`#${sec.toLowerCase()}`}
            onClick={(e) => {
              e.preventDefault();
              document.getElementById(sec.toLowerCase()).scrollIntoView({ behavior: 'smooth' });
            }}
            className={`text-xs writing-vertical tracking-wide transition-all duration-200 cursor-pointer hover:text-blue-400 ${
              activeSection === sec ? 'text-blue-500 font-bold' : 'text-gray-400'
            }`}
            style={{ writingMode: 'vertical-rl', transform: 'rotate(270deg)' }}
          >
            {sec}
          </a>
        ))}
      </div>

      {/* Main content */}
      <div className="ml-24 flex-1 p-6">
        <div className="max-w-6xl mx-auto space-y-32">
          <section id="About" ref={el => (refs.current['about'] = el)} className="min-h-screen flex items-center">
            <div className="flex flex-col lg:flex-row items-center gap-8 w-full">
              <div className="space-y-2 text-left flex-1 lg:pl-8">
                {typedLines.map((line, idx) => (
                  <div key={`done-${loop}-${idx}`} className="whitespace-pre">{highlightLine(line)}</div>
                ))}
                {lineIndex < fullLines.length && (
                  <div className="whitespace-pre">
                    {highlightPartial(currentLine)}
                    <span className="border-r-2 border-gray-400 animate-blink">&nbsp;</span>
                  </div>
                )}
              </div>
              <div className="flex-1 hidden lg:block">
                <Lottie animationData={codingAnimation} loop={true} />
              </div>
            </div>
          </section>

          <section id="Skills" ref={el => (refs.current['skills'] = el)} className="min-h-screen flex items-center">
            <div className="w-full">
              <h1 className="text-2xl mb-10 text-[#4FC1FF] text-center">Skills</h1>
              <div className="space-y-10 max-w-4xl mx-auto">
                <div className="text-center">
                  <h2 className="text-lg font-semibold text-[#4FC1FF] mb-4">💻 Technical</h2>
                  <div className="space-y-2">
                    <p className="text-sm"><span className="text-[#9CDCFE]">languages</span> = <span className="text-[#ce9178]">["Python", "Java", "C", "OCaml", "SQL", "JavaScript"]</span></p>
                    <p className="text-sm"><span className="text-[#9CDCFE]">frameworks</span> = <span className="text-[#ce9178]">["React", "Tailwind", "Node.js", "Scikit-learn"]</span></p>
                  </div>
                </div>

                <div className="text-center">
                  <h2 className="text-lg font-semibold text-[#4FC1FF] mb-4">⚙️ Tools</h2>
                  <div className="space-y-2">
                    <p className="text-sm"><span className="text-[#9CDCFE]">tools</span> = <span className="text-[#ce9178]">["Git", "Jupyter", "Excel", "PowerPoint", "VS Code"]</span></p>
                  </div>
                </div>

                <div className="text-center">
                  <h2 className="text-lg font-semibold text-[#4FC1FF] mb-4">📈 Finance / Data</h2>
                  <div className="space-y-2">
                    <p className="text-sm"><span className="text-[#9CDCFE]">finance_skills</span> = <span className="text-[#ce9178]">["Portfolio Optimization", "Regression", "Backtesting", "A/B Testing"]</span></p>
                  </div>
                </div>
              </div>
            </div>
          </section>

          <section id="Projects" ref={el => (refs.current['projects'] = el)} className="min-h-screen flex items-center">
            <div className="w-full">
              <h1 className="text-2xl mb-10 text-[#4FC1FF] text-center">Projects</h1>
              <div className="max-w-4xl mx-auto">
                <ul className="space-y-4 text-sm text-center">
                  <li className="flex flex-col items-center">
                    <strong className="text-[#4FC1FF] mb-1">Flash Crash Analysis</strong>
                    <span>Regression analysis on high-frequency data confirming Welch & Goyal's predictor limits.</span>
                  </li>
                  <li className="flex flex-col items-center">
                    <strong className="text-[#4FC1FF] mb-1">Portfolio Optimization</strong>
                    <span>Used Python and convex optimization to build efficient frontiers.</span>
                  </li>
                  <li className="flex flex-col items-center">
                    <strong className="text-[#4FC1FF] mb-1">OCaml Type Checker</strong>
                    <span>Custom optimizer for OCaml using type inference and syntax trees.</span>
                  </li>
                  <li className="flex flex-col items-center">
                    <strong className="text-[#4FC1FF] mb-1">Solar Power Story</strong>
                    <span>Visualized Indian solar trends; recognized on Kaggle for storytelling.</span>
                  </li>
                </ul>
              </div>
            </div>
          </section>

          <section id="Experience" ref={el => (refs.current['experience'] = el)} className="min-h-screen flex items-center">
            <div className="w-full">
              <h1 className="text-2xl mb-10 text-[#4FC1FF] text-center">Experience</h1>
              <div className="max-w-4xl mx-auto">
                <div className="space-y-8 text-sm">
                  <div className="text-center">
                    <h2 className="text-lg font-semibold text-[#4FC1FF] mb-4">💼 Professional Experience</h2>
                    <div className="space-y-6">
                      <div className="flex flex-col items-center">
                        <strong className="text-[#9CDCFE] mb-2">Software Engineering Intern @ BuzzClan</strong>
                        <span className="text-[#d4d4d4]">Developed and maintained enterprise applications</span>
                      </div>
                      <div className="flex flex-col items-center">
                        <strong className="text-[#9CDCFE] mb-2">Researcher @ UMD Climate Lab</strong>
                        <span className="text-[#d4d4d4]">Regression & uncertainty modeling for climate data analysis</span>
                      </div>
                    </div>
                  </div>

                  <div className="text-center">
                    <h2 className="text-lg font-semibold text-[#4FC1FF] mb-4">👨‍🏫 Teaching & Leadership</h2>
                    <div className="space-y-6">
                      <div className="flex flex-col items-center">
                        <strong className="text-[#9CDCFE] mb-2">TA for Calculus I & II</strong>
                        <span className="text-[#d4d4d4]">Mentored students, designed curriculum, improved outcomes</span>
                      </div>
                      <div className="flex flex-col items-center">
                        <strong className="text-[#9CDCFE] mb-2">Co-founder @ Ruhin Education</strong>
                        <span className="text-[#d4d4d4]">Built edtech platform for special needs students</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>

          <section id="Contact" ref={el => (refs.current['contact'] = el)} className="min-h-screen flex items-center">
            <div className="w-full">
              <h1 className="text-2xl mb-10 text-[#4FC1FF] text-center">Contact</h1>
              <div className="max-w-4xl mx-auto">
                <div className="space-y-4 text-sm text-center">
                  <p className="flex flex-col items-center">
                    <span className="text-[#4FC1FF] mb-1">Email</span>
                    <a href="mailto:chetanyamakkar99@gmail.com" className="hover:text-blue-400 transition-colors">chetanyamakkar99@gmail.com</a>
                  </p>
                  <p className="flex flex-col items-center">
                    <span className="text-[#4FC1FF] mb-1">LinkedIn</span>
                    <a href="https://www.linkedin.com/in/chetanyamakkar/" target="_blank" className="text-blue-400 hover:text-blue-300 transition-colors">linkedin.com/in/chetanyamakkar</a>
                  </p>
                  <p className="flex flex-col items-center">
                    <span className="text-[#4FC1FF] mb-1">GitHub</span>
                    <a href="https://github.com/chetanyamakkar11" target="_blank" className="text-blue-400 hover:text-blue-300 transition-colors">github.com/chetanyamakkar11</a>
                  </p>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}
